import json
import csv
import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

# --- Load and normalize Source A (JSON, highest priority) ---
with open('/data/source_a/users.json') as f:
    source_a_raw = json.load(f)

source_a = {}
for user in source_a_raw:
    uid = user['id']
    source_a[uid] = {
        'user_id': uid,
        'name': user['full_name'],
        'email': user['email'],
        'created_date': user['registration_date'],
        'status': user.get('status'),
    }

# --- Load and normalize Source B (CSV) ---
source_b = {}
with open('/data/source_b/users.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        uid = int(row['user_id'])
        source_b[uid] = {
            'user_id': uid,
            'name': row['name'],
            'email': row['email_address'],
            'created_date': row['created_at'],
            'status': row.get('is_active', '').lower() if row.get('is_active') else None,
        }

# --- Load and normalize Source C (Parquet, lowest priority) ---
df_c = pd.read_parquet('/data/source_c/users.parquet')
source_c = {}
for _, row in df_c.iterrows():
    uid = int(row['userId'])
    source_c[uid] = {
        'user_id': uid,
        'name': row['userName'],
        'email': row['email'],
        'created_date': row['joined'],
        'status': str(row['active']).lower() if pd.notna(row['active']) else None,
    }

sources = {'source_a': source_a, 'source_b': source_b, 'source_c': source_c}
priority = ['source_a', 'source_b', 'source_c']

# Collect all unique user IDs
all_user_ids = set()
for src in sources.values():
    all_user_ids.update(src.keys())

fields = ['name', 'email', 'created_date', 'status']
merged = {}
conflicts = []

for uid in sorted(all_user_ids):
    merged[uid] = {'user_id': uid}

    for field in fields:
        values = {}
        for src_name in priority:
            src = sources[src_name]
            if uid in src and field in src[uid] and src[uid][field] is not None and src[uid][field] != '':
                values[src_name] = src[uid][field]

        if not values:
            continue

        # Pick the value from the highest-priority source that has it
        selected = None
        for src_name in priority:
            if src_name in values:
                selected = values[src_name]
                break

        merged[uid][field] = selected

        # Record conflict if multiple sources differ
        unique_values = set(str(v) for v in values.values())
        if len(unique_values) > 1:
            conflicts.append({
                'user_id': uid,
                'field': field,
                'values': {
                    'source_a': values.get('source_a'),
                    'source_b': values.get('source_b'),
                    'source_c': values.get('source_c'),
                },
                'selected': selected,
            })

# --- Write merged Parquet ---
records = [merged[uid] for uid in sorted(all_user_ids)]
schema = pa.schema([
    ('user_id', pa.int64()),
    ('name', pa.string()),
    ('email', pa.string()),
    ('created_date', pa.string()),
    ('status', pa.string()),
])
table = pa.Table.from_pylist(records, schema=schema)
pq.write_table(table, '/app/merged_users.parquet')

# --- Write conflict report ---
report = {
    'total_conflicts': len(conflicts),
    'conflicts': conflicts,
}
with open('/app/conflicts.json', 'w') as f:
    json.dump(report, f, indent=2)

print(f"Merged {len(records)} users")
print(f"Found {len(conflicts)} conflicts")
for c in conflicts:
    print(f"  user {c['user_id']} '{c['field']}': {c['values']} -> {c['selected']}")

